import React from 'react';
import { GameState, Hero, Position } from '../../types/game';
import '../../styles/components/GameMap.css';

interface GameMapProps {
  gameState: GameState;
  selectedHero: Hero | null;
  onTileClick: (position: Position) => void;
  onHeroClick: (heroId: string) => void;
  onCityClick: (cityId: string) => void;
  isPlayerTurn: boolean;
}

const GameMap: React.FC<GameMapProps> = ({
  gameState,
  selectedHero,
  onTileClick,
  onHeroClick,
  onCityClick,
  isPlayerTurn
}) => {
  if (!gameState?.map?.size) {
    console.error("Map data missing:", gameState);
    return <div>Error: No map data</div>;
  }

  const renderTile = (x: number, y: number) => {
    const index = y * gameState.map.size.width + x;
    const tile = gameState.map.tiles[index];
    
    // Encontrar si hay un héroe en esta posición
    const hero = [...(gameState.player?.heroes || []), ...(gameState.ai?.heroes || [])]
      .find(h => h.position.x === x && h.position.y === y);

    return (
      <div
        key={`tile-${x}-${y}`}
        className={`map-tile ${tile?.terrain || 'grass'} ${hero ? 'has-hero' : ''}`}
        onClick={() => onTileClick({ x, y })}
      >
        {hero && (
          <div 
            className={`hero-sprite ${gameState.current_player}-hero`}
            onClick={(e) => {
              e.stopPropagation();
              onHeroClick(hero.id);
            }}
          >
            H
          </div>
        )}
      </div>
    );
  };

  const rows = [];
  for (let y = 0; y < gameState.map.size.height; y++) {
    const row = [];
    for (let x = 0; x < gameState.map.size.width; x++) {
      row.push(renderTile(x, y));
    }
    rows.push(
      <div key={`row-${y}`} className="map-row">
        {row}
      </div>
    );
  }

  return (
    <div className="game-map">
      {rows}
    </div>
  );
};

export default GameMap;
